(() => { const g=__dmh, D=g.data.enemies; let foreign=0, n=0; const seen={};
for(let r=1;r<=16;r++){ g.round=r; for(let i=0;i<3000;i++){ const t=g.pickEnemyType(); n++; if(D[t].map!==g.mapId) foreign++; seen[D[t].name]=(seen[D[t].name]||0)+1; } }
// and the guard: ask for every creature in the game by index; what comes out must belong here
let guard=0; const V=g.player.pos.constructor; for(let i=0;i<D.length;i++){ const E=g.spawnEnemy(i,new V(0,-5000,0),false,-1,1,1,0,false); if(E.def.map!==g.mapId||g.data.enemies[E.defIndex].map!==g.mapId) guard++; E.dead=true; E.remove=true; E.puppet.visible=false; }
g.round=0; return JSON.stringify({map:g.map.name, picks:n, foreign, guardFails:guard, kinds:Object.keys(seen).length, seen}); })()
